function forjaHideProfileRetry(){const b=$("#loginProfileRetry");if(b){b.classList.add("hidden");b.onclick=null;}}
function forjaProfileError(code,status=0){const e=new Error(code);e.code=code;e.status=status;return e;}
function forjaProfileRetryable(e){return e?.code==='FORJA_PROFILE_TIMEOUT'||e instanceof TypeError||[408,500,502,503,504].includes(e?.status);}
function forjaProfileMessage(e){
 if(e?.code==='FORJA_PROFILE_TIMEOUT')return "O servidor demorou para validar seu perfil. Ele pode estar iniciando. Tente novamente em instantes.";
 if(e instanceof TypeError||[408,500,502,503,504].includes(e?.status))return "Não foi possível alcançar o servidor FORJA. Verifique sua conexão e tente novamente em instantes.";
 if(e?.status===429)return "Muitas tentativas. Aguarde um pouco e tente novamente.";
 if(e?.status===401)return "Não foi possível validar sua sessão. Entre novamente com seu e-mail e senha.";
