}
async function forjaProfileOnce(session,operation){
 const controller=new AbortController();let timer,rejectCanceled;
 const canceled=()=>{rejectCanceled?.(forjaStaleSession());controller.abort();};operation.controller.signal.addEventListener('abort',canceled,{once:true});
 try{
  if(operation.controller.signal.aborted)throw forjaStaleSession();
  return await Promise.race([
   api('/me',{session,signal:controller.signal}),
   new Promise((_,reject)=>{rejectCanceled=reject;timer=setTimeout(()=>{reject(forjaProfileError('FORJA_PROFILE_TIMEOUT'));controller.abort();},20000);})
  ]);
 }finally{clearTimeout(timer);operation.controller.signal.removeEventListener('abort',canceled);controller.abort();}
}
async function forjaProfilePause(operation){
 let timer;const signal=operation.controller.signal;
 await new Promise((resolve,reject)=>{const canceled=()=>{clearTimeout(timer);reject(forjaStaleSession());};if(signal.aborted)return canceled();signal.addEventListener('abort',canceled,{once:true});timer=setTimeout(()=>{signal.removeEventListener('abort',canceled);resolve();},1000);});
}
async function getProfile(session,operation){
 for(let attempt=0;attempt<2;attempt++){
  try{
   const me=await forjaProfileOnce(session,operation);forjaAssertSession(session);
   if(forjaProfileOperation!==operation)throw forjaStaleSession();
   if(!me?.profile||!Object.hasOwn(ROLE_UI,me.profile.role)||me.profile.active!==true||(me.uid&&me.uid!==session.uid)||(me.profile.uid&&me.profile.uid!==session.uid))throw forjaProfileError('FORJA_PROFILE_INVALID');
   return me.profile;
  }catch(e){
   if(!forjaSessionCurrent(session)||forjaProfileOperation!==operation)throw forjaStaleSession();
   if(attempt||!forjaProfileRetryable(e))throw e;
   updateProcess("Aguardando o servidor...","O servidor pode estar iniciando. Faremos mais uma tentativa limitada.","Conta");
